// neon.js — NÉON, a minimalist brick breaker (zero dependencies).
//
// This file INTENTIONALLY mixes game logic and rendering in a few places
// (see ISSUES.md #2): brick collision detection currently lives inside the
// draw loop `frame()`. This is deliberate debt, ripe for a refactor.
//
// The module runs nothing on import: only `boot()` touches the DOM. Pure
// logic can therefore be imported from the tests (`node --test`) without a
// browser.

import { palette, brickColor } from './theme.js';
import { createGlowMap, drawGlow, GLOW_W, GLOW_H } from './bloom.js';

// --- Axis convention -------------------------------------------------------

// Screen coordinates, as the canvas defines them: the origin is the TOP-LEFT
// corner and **Y GROWS DOWNWARD**. So `y = 0` is the ceiling, `y = HEIGHT` the
// line through which the ball is lost, and a ball climbing toward the bricks
// has a NEGATIVE `vy`. Every sign in this file follows from that single
// choice — the launch velocity, each bounce, and the paddle test `vy > 0`.
//
// The constants below name the sign a velocity component takes per heading.
// Assert against them rather than against a bare `-1` / `1`: a test reading
// `Math.sign(ball.vy) === UP` states its intent, where a hard-coded `-1` only
// states an arithmetic fact and quietly means the opposite if the convention
// ever flips.
//
//   UP    (-1)  toward the ceiling and the bricks
//   DOWN  (+1)  toward the paddle and the loss line
//   LEFT  (-1)  toward x = 0
//   RIGHT (+1)  toward x = WIDTH

export const UP = -1;
export const DOWN = 1;
export const LEFT = -1;
export const RIGHT = 1;

// --- Field constants -------------------------------------------------------

export const WIDTH = 640;
export const HEIGHT = 480;

export const PADDLE_W = 96;
export const PADDLE_H = 12;
export const PADDLE_Y = HEIGHT - 32;

export const BALL_R = 7;

export const BRICK_ROWS = 5;
export const BRICK_COLS = 8;
export const BRICK_W = 72;
export const BRICK_H = 20;
export const BRICK_GAP = 8;
export const BRICK_TOP = 48;

const STORAGE_KEY = 'neon.best';

// --- State construction ----------------------------------------------------

// Builds the brick grid for a given level.
// The higher the level, the more points bricks are worth.
export function makeBricks(level = 1) {
  const bricks = [];
  const offsetX = (WIDTH - (BRICK_COLS * (BRICK_W + BRICK_GAP) - BRICK_GAP)) / 2;
  for (let row = 0; row < BRICK_ROWS; row++) {
    for (let col = 0; col < BRICK_COLS; col++) {
      bricks.push({
        x: offsetX + col * (BRICK_W + BRICK_GAP),
        y: BRICK_TOP + row * (BRICK_H + BRICK_GAP),
        w: BRICK_W,
        h: BRICK_H,
        row,
        alive: true,
        points: (BRICK_ROWS - row) * 10 * level,
      });
    }
  }
  return bricks;
}

// Ball speed as a function of the level (ramps up with each level).
export function ballSpeed(level = 1) {
  return 260 + (level - 1) * 90;
}

// Creates a fresh game state.
export function createState(level = 1) {
  const speed = ballSpeed(level);
  return {
    level,
    lives: 3,
    score: 0,
    combo: 0,
    best: 0,
    running: false,
    paddle: { x: (WIDTH - PADDLE_W) / 2, y: PADDLE_Y, w: PADDLE_W, h: PADDLE_H },
    ball: { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 2, r: BALL_R, vx: speed * 0.5, vy: -speed },
    bricks: makeBricks(level),
  };
}

// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Score & combo (NOT covered by tests — debt #5) ------------------------

// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

// Points earned for breaking a brick, combo included.
export function scoreForBrick(brick, combo) {
  return Math.round(brick.points * comboMultiplier(combo));
}

// --- Best score persistence ------------------------------------------------

// Reads the best score from a localStorage-compatible storage.
// Robust to corrupted or missing storage: returns 0 instead of throwing.
export function loadBest(storage) {
  if (!storage) return 0;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) && value > 0 ? value : 0;
  } catch {
    return 0;
  }
}

// Writes the best score if the current score beats it. Returns the updated best.
export function saveBest(storage, score) {
  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
    return score;
  }
  return best;
}

// --- Physics (movement + wall/paddle bounces) ------------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Does NOT handle bricks: that responsibility still
// lives in the render loop `frame()` (debt #2).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

// --- Rendering (DOM): brick collision logic STILL mixed in here ------------

// Main render loop. For each live brick we test collision AND draw in the same
// pass: this is where logic and rendering are entangled.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: collision + bounce + score + drawing, all in one place.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    if (collides(state.ball, brick)) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
      // BUG (#1): the ball is NOT deflected here. Only the walls and the paddle
      // bounce (in step()); bricks were never given a bounce. So the ball plows
      // straight through a column head-on AND straight through the side of a
      // row. Fix = a real per-face bounce (flip vy on a top/bottom hit, vx on a
      // side hit) plus pushing the ball back out of the brick.
    }

    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

  // Paddle — color hard-coded instead of using the palette (inconsistency #6).
  ctx.fillStyle = '#00e5ff';
  ctx.fillRect(state.paddle.x, state.paddle.y, state.paddle.w, state.paddle.h);

  // Ball — also hard-coded (#6).
  ctx.fillStyle = '#39ff14';
  ctx.beginPath();
  ctx.arc(state.ball.x, state.ball.y, state.ball.r, 0, Math.PI * 2);
  ctx.fill();

  // HUD
  ctx.fillStyle = palette.text;
  ctx.font = '16px monospace';
  ctx.fillText(`Score ${state.score}`, 12, 24);
  ctx.fillText(`Best ${state.best}`, WIDTH - 110, 24);
  ctx.fillText(`Lives ${state.lives}`, WIDTH / 2 - 30, 24);
}

// --- Boot (browser entry point) --------------------------------------------

// Starts the game: wires up the canvas, the mouse and the animation loop.
// The only function that depends on the DOM; never called on import.
export function boot(doc = document) {
  const canvas = doc.getElementById('game');
  const ctx = canvas.getContext('2d');
  canvas.width = WIDTH;
  canvas.height = HEIGHT;

  const state = createState(1);
  state.best = loadBest(doc.defaultView?.localStorage ?? globalThis.localStorage);
  state.running = true;

  // Glow pass: a coarse offscreen light map, stretched over the field.
  const offscreen = doc.createElement('canvas');
  offscreen.width = GLOW_W;
  offscreen.height = GLOW_H;
  const glow = {
    map: createGlowMap(),
    image: offscreen.getContext('2d').createImageData(GLOW_W, GLOW_H),
  };

  // Move the paddle with the mouse.
  canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left - state.paddle.w / 2;
    state.paddle.x = Math.max(0, Math.min(WIDTH - state.paddle.w, x));
  });

  let last = performance.now();
  function loop(now) {
    const dt = Math.min((now - last) / 1000, 0.05);
    last = now;

    if (state.running) {
      const lost = step(state, dt);
      if (lost) {
        state.lives -= 1;
        state.combo = 0;
        if (state.lives <= 0) {
          state.best = saveBest(globalThis.localStorage, state.score);
          Object.assign(state, createState(state.level));
          state.best = loadBest(globalThis.localStorage);
        } else {
          // relaunch the ball
          state.ball = createState(state.level).ball;
        }
      }

      // Level cleared: all bricks broken
      if (state.bricks.every((b) => !b.alive)) {
        state.level += 1;
        state.bricks = makeBricks(state.level);
        state.ball = createState(state.level).ball;
      }
    }

    frame(ctx, state);
    drawGlow(ctx, glow, state, WIDTH, HEIGHT, offscreen);
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);

  return state;
}

// neon.test.js — PARTIAL coverage (on purpose).
//
// What is covered today: the collision primitive and a couple of physics
// bounces. What is NOT covered yet: score and combo (see ISSUES.md #5), nor
// level progression. This is a starting point for the testing work ahead, not
// a complete suite.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

// TODO (#5): test comboMultiplier / scoreForBrick.
// TODO      : test level progression and loadBest/saveBest persistence.

Le fichier ISSUES.md #1 décrit précisément ce qu'il faut faire :
- **par face** : l'axe avec la plus petite pénétration est la face touchée → flip `vy` sur un hit haut/bas, `vx` sur un hit côté, et laisser l'autre composante inchangée
- **coin** : pénétrations égales → flip les deux composantes
- **push out** : repositionner la balle hors de la brique (sinon sticky bounce / re-flip infini)
- **voisins** : le gap est de 8px et le diamètre de la balle 14px, donc chaque couture chevauche deux briques dans le même passage → le rebond doit s'appliquer exactement une fois (`vy = -vy` appliqué deux fois s'annule)

C'est important : si je borne le flip dans la detection de face, mais que la balle chevauche deux briques, appliquer le rebond pour chaque brique peut s'annuler. Le point "voisins" dit que chaque couture chevauche deux briques dans le même passage et qu'il faut que le rebond s'applique exactement une fois.

Donc je devrais gérer la collision en un seul endroit, en ne traitant efficacement qu'une seule brique qui sera touchée, ou en s'assurant que le rebond ne s'applique qu'une fois.

L'approche la plus propre : traiter la collision de manière groupée. Mais pour rester dans l'esprit de la correction minimale de #1, je vais créer une fonction pure testable `bounceOffBrick` qui gère le rebond ET le push-out pour une brique. 

Cependant le problème des voisins reste. Si la balle chevauche deux briques dans le même passage, appliquer deux fois le rebond de déplacement pourrait ramener la balle dans la brique. Mais avec un push-out complet dans l'autre sens... Hmm.

Réfléchissons. Le commentaire dit que le rebond doit s'appliquer exactement une fois. Le plus simple pour garantir ça : après avoir trouvé la brique touchée et appliqué le rebond, ne pas appliquer de rebond aux autres briques que la balle chevauche encore (car la première résolution a déjà défini la nouvelle position/vitesse).

Mais l'ordre dans `frame()` est séquentiel sur les briques. Si la balle va vers la droite à travers une couture verticale (chevauche deux briques côte à côte), les deux briques vont être touchées. Le premier applique `vx = -vx` et push-out x. Le second... la balle a été poussée hors de la première mais peut encore chevaucher la seconde. Appliquer `vx = -vx` encore s'annule → traversée.

Pour éviter cela, la meilleure approche : regrouper les briques touchées en une seule résolution. Je vais faire passer la logique de rebond dans une fonction qui traite toutes les briques chevauchées d'un coup (trouver celles qui se chevauchent, appliquer UN rebond). 

En fait, une approche robuste pour les voisins : détecter toutes les briques touchées, mais appliquer le rebond/l'anti-pénétration total une seule fois. Le push-out total déplace la balle hors de TOUTES les briques touchées.

Je vais créer une fonction `resolveBricks(ball, bricks)` qui :
1. Collecte les briques vivantes chevauchées par la balle.
2. Détruit chacune, marque le score etc. — mais le rebond une seule fois.

Attendez, mais score/combo doivent être appliqués pour chaque brique détruite. Donc on doit parcourir toutes les briques chevauchées pour les détruire et scorer. Mais le flip ne doit être fait qu'une fois.

Reprenons. L'ampleur : je dois respecter les exigences de #1. Je vais implémenter une fonction pure testable, disons `bounceBallOffBricks(ball, bricks)` qui retourne les briques touchées (pour le scoring) et nettoie la collision. Mais attention à la contrainte issue #2 de ne pas changer l'API publique. 

Mais en fait je peux bien faire ça dans frame, en collectant les hits d'abord puis en résolvant la collision une fois, puis scorer. Mais les points/score dépendent des briques détruites. Je peux :

```js
function frame(ctx, state) {
  ...
  // collect hits
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    if (collides(state.ball, brick)) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }
  }
  ...
}
```

Mais le rebond doit être fait après avoir identifié toutes les briques touchées (pour éviter le double flip). Je vais donc séparer en deux étapes :
1. Détruire les briques touchées + scorer.
2. Appliquer exactement un rebond avec push-out complet hors de toutes les briques.

Pour le push-out "hors de toutes les briques touchées", le plus simple est de pousser la balle hors de la zone regroupée des briques touchées, ou simplement appliquer le rebond selon l'axe à plus petite pénétration globale et pousser assez loin.

Le plus robuste : pousser la balle le long de l'axe de rebond jusqu'à ce qu'elle ne chevauche plus aucune des briques touchées. Mais ça peut être complexe.

Approche plus simple originale (comme l'esprit de #1 "par face") : déterminer la face la plus probable basée sur la direction de la balle et la position relative à la brique (le bord de la brique vers lequel la balle voyage).

En fait, la meilleure approche pour déterminer la face quand on a plusieurs briques : utiliser le "plus petit overlap" global parmi toutes les briques touchées, comme le préconise #1 pour une seule brique. Pour éviter le double flip avec les voisins, on applique le rebond une seule fois.

Plan :
- Collecter les briques vivantes chevauchées.
- Les marquer détruites et scorer.
- S'il y a au moins un hit, calculer le rebond : déterminer l'axe de pénétration min global (considérant la "bounding box" unifiée des briques touchées, ou bien faire une fusion). 

Hmm, le plus simple et robuste : unifier les briques touchées en une bounding box englobante et traiter la balle contre cette boîte pour le rebond. C'est élégant et règle le problème des voisins (une boîte au lieu de deux). 

Cependant, une couture pourrait être en diagonale (deux briques en diagonale). La bounding box englobante serait plus grande mais ça fonctionnerait raisonnablement pour un rebond de type breakout.

Mais attention : pour le cas de deux briques alignées horizontalement, la bbox englobe les deux. La balle arrivant du dessus, pénétration y petite → flip vy. Correct.

Pour deux briques alignées verticalement, bbox englobe les deux, balle du côté → flip vx. Correct.

Je pense que cette approche par bbox est propre et résout le problème des voisins. Toutefois, je m'écarte peut-être de l'esprit "par face". Mais l'exigence principale de #1 est que le rebond s'applique exactement une fois.

Réfléchissons à ce qui est le plus aligné avec les tests "rouges d'abord" demandés dans #1. L'issue demande d'ajouter chaque cas comme test rouge d'abord. Donc je devrais probablement aussi ajouter des tests.

Je vais créer une fonction pure exportée testable qui fait la résolution du rebond pour une collection de briques. Appelons-la `brickHit(ball, bricks)` conformément à #2 (extraction d'une fonction pure testable). Ça ne change pas l'API publique existante ; ça ajoute une fonction.

En fait #2 demande `brickHit(ball, bricks)` sans changer l'API publique. Je vais extraire cette fonction. Elle devrait :
- trouver/détruire les briques touchées
- retourner quelque chose pour permettre le scoring

Définissons : `brickHit(ball, bricks)` détruit les briques touchées et applique le rebond exactement une fois sur ball. Elle retourne le nombre de briques touchées (pour que frame incrémente combo/score).

Mais le scoring a besoin de chaque brique (ses points). Je vais plutôt retourner la liste des briques touchées. Alors frame peut scorer.

Définissons :
```js
export function brickHit(ball, bricks) {
  const hits = [];
  for (const brick of bricks) {
    if (brick.alive && collides(ball, brick)) {
      brick.alive = false;
      hits.push(brick);
    }
  }
  if (hits.length > 0) {
    bounceBall(ball, hits);
  }
  return hits;
}
```

Et `bounceBall(ball, hits)` calcule la bbox englobante des hits et effectue le rebond par face min + push-out.

Ensuite frame :
```js
for (const brick of state.bricks) {
  if (!brick.alive) continue;
  const hits = ... 
}
```

En fait je veux détruire+scorer dans frame. Utilisons brickHit pour le rebond, et scorer pour les briques détruites. Mais frame itère normalement les briques pour dessiner. Ici je vais appeler brickHit une fois avant, puis dessiner les briques vivantes.

Refactor frame :
```js
export function frame(ctx, state) {
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // collision: destroy hit bricks, bounce the ball exactly once
  const hits = brickHit(state.ball, state.bricks);
  for (const brick of hits) {
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }
  ...
}
```

Mais il y a le problème du "re-flip infini" même avec push-out, car frame est appelé chaque frame. Le push-out garantit que la balle est hors de la brique à la fin. Mais avec la bbox englobante, la balle est poussée hors de la bbox. OK.

Toutefois, il peut rester un problème : la balle est poussée hors de la bbox mais traverse une autre brique non encore traitée ? Non, toutes les briques étaient "toutes les briques Touchées" dans cette passe. La balle poussée hors de la bbox unifiée ne chevauche plus aucune des briques touchées (car elles sont dans la bbox). 

Maintenant implémentons `bounceBall(ball, hits)` avec la bbox. Mais attendons — le problème de base "par face" suppose une seule brique. Avec plusieurs briques, une bbox est une simplification raisonnable. Pour un hit simple, la bbox = la brique, donc comportement exactement décrit par #1. Bien.

Calcul du rebond :
```js
function bounceBall(ball, bricks) {
  // bounding box of all hit bricks
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const b of bricks) {
    minX = Math.min(minX, b.x);
    minY = Math.min(minY, b.y);
    maxX = Math.max(maxX, b.x + b.w);
    maxY = Math.max(maxY, b.y + b.h);
  }
  // remaining penetrations
  const penLeft = ball.x + ball.r - minX;
  const penRight = maxX - (ball.x - ball.r);
  const penTop = ball.y + ball.r - minY;
  const penBottom = maxY - (ball.y - ball.r);
  const dx = Math.min(penLeft, penRight);
  const dy = Math.min(penTop, penBottom);

  if (dx < dy) {
    // side hit
    if (penLeft < penRight) {
      ball.x = minX - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = maxX + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
  } else if (dy < dx) {
    // top/bottom hit
    if (penTop < penBottom) {
      ball.y = minY - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = maxY + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
  } else {
    // corner: equal -> flip both
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    // push out along the smaller of the two? equal penetration: push along x and y
    ball.x += (penLeft < penRight ? -penLeft : penRight) ... 
  }
}
```

Pour le coin (pénétrations égales), push-out dans les deux axes :
```js
} else {
  ball.vx = -ball.vx;
  ball.vy = -ball.vy;
  if (penLeft < penRight) ball.x = minX - ball.r;
  else ball.x = maxX + ball.r;
  if (penTop < penBottom) ball.y = minY - ball.r;
  else ball.y = maxY + ball.r;
}
```

Mais si pénétration égale exactement sur les deux axes avec penLeft == penRight et penTop == penBottom... cas rare. On peut choisir de pousser vers l'extérieur selon la direction de la balle. Mais pour simplifier, dans le coin, je pousse sur x vers le côté où la balle vient (le bord avec la plus petite pénétration sera l'un des deux bords ; si égal, prendre le bord duquel la balle vient). Puisqu'on est dans equal dx==dy, pour pousser il faut quand même choisir un sens.

Pour le push-out dans le coin, je pousse selon la direction de la vitesse pour sortir proprement :
```js
// corner
ball.vx = -ball.vx;
ball.vy = -ball.vy;
// push out along each axis away from the brick
if (penLeft < penRight) ball.x = minX - ball.r; else ball.x = maxX + ball.r;
if (penTop < penBottom) ball.y = minY - ball.r; else ball.y = maxY + ball.r;
```
Ceci est consistant. OK.

Maintenant, le point sur "neighbours : rebond appliqué exactement une fois". Avec l'approche bbox, on applique le rebond une seule fois par passe (car `bounceBall` n'est appelée qu'une fois si hits non vide). Bon.

Maintenant le push-out garanti de sortir la balle hors de la bbox. Mais il faut s'assurer que push-out ne pose pas la balle dans une autre brique voisine qui n'est pas dans hits. Toutes les briques chevauchées dans cette passe sont dans hits et donc dans la bbox. Une brique pas chevauchée ne sera pas sur la nouvelle position si on pousse juste au bord de la bbox vers l'extérieur. Le bord extérieur de la bbox — en dehors — ne peut contenir qu'une brique adjacente. Par exemple, bbox de deux briques horizontales ; balle poussée à `minX - r` vers la gauche : c'est à côté d'une colonne de briques à gauche. Si la balle est réellement juste au-dessus (hit vertical) on ne pousserait pas x. L'axe de push correspond à l'axe de pénétration min, donc on pousse vers la face réellement touchée, qui est un bord extérieur de la bbox. Juste à l'extérieur de ce bord, par construction (gap 8px > 2*r? Non, r=7, gap=8, donc 2r=14>8, la balle dépasserait).

Hmm, en poussant `minX - r`, la balle a son bord gauche à `minX - 2r`. Si une brique est juste à gauche séparée par un gap de 8, la brique à gauche s'étend de `minX - 8 - 72` à `minX - 8`. Le bord droit de cette brique est à `minX - 8`. Le bord gauche de la balle est à `minX - 14`, qui est < minX - 8, donc la balle chevauche la brique gauche ! C'est le cas "voisins latéraux même passe" mais dans la passe suivante elle sera traitée. Mais grâce au push-out, à la prochaine frame, la balle se déplacera et le rebond se fera contre la brique gauche correctement. Ce n'est pas un "re-flip infini" de la même brique puisqu'on l'a poussée hors de la brique d'origine.

En fait le "sticky bounce" redouté dans #1 c'est quand la balle reste chevauchante de la MÊME brique à cause d'un push-out insuffisant, causant flip répété. Avec un push-out complet hors de la brique touchée, ce sticky disparaît. Le chevauchement de la brique voisine (différente) est géré à la passe suivante et n'est pas sticky. OK.

Donc l'essentiel : flip une fois par passe + push-out complet. Mon approche le fait.

Cependant, il y a le problème du tunneling mentionné (#1). Mais les tests demandés sont "par face", "coin", "push out", "neighbours", "tunnelling". L'issue dit d'ajouter chaque cas comme test rouge d'abord. La correction principale est le rebond. Le tunnelling est une considération avancée. Je vais me concentrer sur le rebond + neighbours + push-out (le cœur du bug "traverse les briques"). Le tunnelling n'est pas le bug décrit ici (la balle "traverse les briques" mais probablement pas à cause du tunnelling à niveau 6 ; plutôt à cause de l'absence totale de rebond). 

Le user dit : "La balle traverse les briques au lieu de rebondir. Corrige ça." C'est précisément l'absence de rebond. Je vais me concentrer sur le rebond et le push-out, avec exactement une application par passe. Je peux également ajouter les tests.

Implémentons. Je vais éditer neon.js : ajouter `bounceBall` (interne), `brickHit` (exportée), et refactorer frame.

Laissez-moi structurer : mettre `brickHit` après `collides` dans la section collision. Mais `bounceBall` est interne et utiliser localement. 

Attendons, `brickHit` utilise `ball`, `bricks`, `collides`. Et `bounceBall` est utilisée à l'intérieur de `brickHit`. Je place les deux dans la section "Collision".

Modifions le code.

D'abord ajoutons les fonctions après `collides`.

