export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Pushes the ball out of the hit bricks and flips its velocity exactly once.
// `hits` is the (non-empty) set of bricks the ball overlaps in this pass.
// They are unified into a single bounding box so a ball crossing a seam of two
// adjacent bricks (the 8 px gap vs a 14 px ball) produces ONE deflection, not
// two that cancel out. The axis with the smaller penetration is the face that
// was hit: flip `vy` on a top/bottom hit, `vx` on a side hit; equal
// penetration (a diagonal corner) flips both. The ball is always pushed fully
// outside, otherwise it would overlap again next frame and re-flip forever
// (sticky bounce).
function bounceBall(ball, hits) {
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const b of hits) {
    if (b.x < minX) minX = b.x;
    if (b.y < minY) minY = b.y;
    if (b.x + b.w > maxX) maxX = b.x + b.w;
    if (b.y + b.h > maxY) maxY = b.y + b.h;
  }

  const penLeft = ball.x + ball.r - minX;
  const penRight = maxX - (ball.x - ball.r);
  const penTop = ball.y + ball.r - minY;
  const penBottom = maxY - (ball.y - ball.r);
  const dx = Math.min(penLeft, penRight);
  const dy = Math.min(penTop, penBottom);

  if (dx < dy) {
    // Side hit: flip the horizontal component and push out sideways.
    if (penLeft < penRight) {
      ball.x = minX - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = maxX + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
    return;
  }

  if (dy < dx) {
    // Top/bottom hit: flip the vertical component and push out up/down.
    if (penTop < penBottom) {
      ball.y = minY - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = maxY + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
    return;
  }

  // Corner: equal penetration on both axes — flip both and push out the corners.
  ball.vx = -ball.vx;
  ball.vy = -ball.vy;
  if (penLeft < penRight) ball.x = minX - ball.r;
  else if (penRight < penLeft) ball.x = maxX + ball.r;
  if (penTop < penBottom) ball.y = minY - ball.r;
  else if (penBottom < penTop) ball.y = maxY + ball.r;
}

// Tests the ball against every live brick: destroys every brick it overlaps,
// deflects the ball exactly once, and returns the destroyed bricks so the
// caller can score them. Pure and testable — the render loop only consumes the
// result (debt #2).
export function brickHit(ball, bricks) {
  const hits = [];
  for (const brick of bricks) {
    if (brick.alive && collides(ball, brick)) {
      brick.alive = false;
      hits.push(brick);
    }
  }
  if (hits.length > 0) {
    bounceBall(ball, hits);
  }
  return hits;
}

