// --- Issue #1: the ball must bounce off bricks, not plow through them -----

function makeBrick(x, y, w = 40, h = 20) {
  return { x, y, w, h, row: 0, alive: true, points: 10 };
}

function makeBall(x, y, vx, vy, r = 7) {
  return { x, y, r, vx, vy };
}

test('brickHit #1: ball hits the TOP of a brick => bounce down (flip vy)', () => {
  const ball = makeBall(100, 85, 0, 40); // moving down, just overlapping the top
  const brick = makeBrick(80, 90);
  brickHit(ball, [brick]);
  assert.equal(brick.alive, false, 'the brick is destroyed');
  assert.equal(ball.vy, Math.abs(ball.vy), 'vy flips upward after a top hit');
  assert.ok(ball.y < 90, 'ball is pushed back above the brick');
});

test('brickHit #1: ball hits the LEFT side of a brick => bounce right (flip vx)', () => {
  const ball = makeBall(73, 100, -40, 0); // moving left into the left edge
  const brick = makeBrick(80, 90);
  brickHit(ball, [brick]);
  assert.equal(brick.alive, false, 'the brick is destroyed');
  assert.ok(ball.vx > 0, 'vx flips right after a left-side hit');
  assert.ok(ball.x + ball.r <= 80, 'ball is pushed out to the left of the brick');
});

test('brickHit #1: diagonal corner hit flips BOTH components', () => {
  const brick = makeBrick(80, 90);
  const ball = makeBall(80, 90, 40, 40); // ball centre exactly on the corner
  ball.vx = 40;
  ball.vy = -40;
  brickHit(ball, [brick]);
  assert.equal(brick.alive, false);
  assert.equal(ball.vx, -40, 'vx is negated');
  assert.equal(ball.vy, 40, 'vy is negated');
});

test('brickHit #1: push-out leaves the ball with NO overlap (no sticky bounce)', () => {
  const ball = makeBall(85, 91, 0, 40); // overlapping the top edge
  const brick = makeBrick(80, 90);
  brickHit(ball, [brick]);
  assert.equal(collides(ball, brick), false, 'ball no longer overlaps the brick');
});

test('brickHit #1: a seam hit deflects exactly ONCE (two adjacent bricks)', () => {
  const a = makeBrick(80, 90); // x in [80, 120]
  const b = makeBrick(128, 90); // 8 px gap, x in [128, 168]
  // Ball straddles the seam, driving down into the gap.
  const ball = makeBall(124, 95, 0, 40, 7);
  const hits = brickHit(ball, [a, b]);
  assert.equal(hits.includes(a), true, 'overlaps the left brick');
  assert.equal(hits.includes(b), true, 'overlaps the right brick');
  // A double flip would cancel out; the single deflection must still register.
  assert.equal(ball.vy, Math.abs(ball.vy), 'exactly one vertical deflection');
  assert.equal(ball.vx, 0, 'no horizontal flip leaked through the seam');
});

